 26→  "mongodb": ["mongo"],
 27→  "kubernetes": ["k8s"],
 28→  "docker": ["containerization", "containers"],
 29→  "aws": ["amazon web services"],
 30→  "gcp": ["google cloud", "google cloud platform"],
 31→  "azure": ["microsoft azure"],
 32→  "ci/cd": ["cicd", "ci cd", "continuous integration", "continuous deployment"],
 33→  "machine learning": ["ml"],
 34→  "deep learning": ["dl"],
 35→  "natural language processing": ["nlp"],
 36→  "graphql": ["gql"],
 37→  "rest": ["restful", "rest api", "restful api"],
 38→  "sql": ["structured query language"],
 39→  "nosql": ["no-sql"],
 40→  "html": ["html5"],
 41→  "css": ["css3", "stylesheets"],
 42→  "sass": ["scss"],
