262→        console.error(`Failed to parse resume ${rid}:`, err);
263→        await supabase.from("resumes").update({ status: "failed" }).eq("id", rid);
264→      }
265→    }
266→
267→    // ─── STEP 2: Generate embeddings (cached) ─────────────────────
268→    console.log("Generating embeddings...");
269→    const { data: resumesForEmbedding } = await supabase
270→      .from("resumes")
271→      .select("id, parsed_json, embedding, parsed_text")
272→      .in("id", targetResumeIds);
273→
274→    const needEmbedding = (resumesForEmbedding || []).filter((r: any) => !r.embedding && (r.parsed_json || r.parsed_text));
275→    if (needEmbedding.length > 0) {
276→      // Build summaries for embedding (from parsed_json to reduce injection)
277→      const summaries = needEmbedding.map((r: any) => {
278→        if (r.parsed_json) {
279→          const p = r.parsed_json;
280→          const parts: string[] = [];
281→          if (p.candidate_name) parts.push(p.candidate_name);
282→          if (p.skills_with_evidence) parts.push(`Skills: ${p.skills_with_evidence.map((s: any) => typeof s === 'string' ? s : s.skill || s.name || '').join(', ')}`);
283→          if (p.tools) parts.push(`Tools: ${p.tools.join(', ')}`);
284→          if (p.domain_experience) parts.push(`Domain: ${p.domain_experience}`);
285→          if (p.roles_with_dates) parts.push(`Roles: ${p.roles_with_dates.map((r: any) => `${r.title || r.role || ''} at ${r.company || ''}`).join('; ')}`);
286→          if (p.education) parts.push(`Education: ${p.education.map((e: any) => typeof e === 'string' ? e : `${e.degree || ''} ${e.institution || ''}`).join('; ')}`);
287→          return parts.join('. ').slice(0, 4000);
288→        }
289→        return (r.parsed_text || '').slice(0, 4000);
290→      });
