787→// ── PDF text extraction fallback ───────────────────────────────
788→function extractPdfText(bytes: Uint8Array): string {
789→  const raw = new TextDecoder("latin1").decode(bytes);
790→  const textChunks: string[] = [];
791→  const btEtRegex = /BT\s([\s\S]*?)ET/g;
792→  let block;
793→  while ((block = btEtRegex.exec(raw)) !== null) {
794→    const parenRegex = /\(([^)]*)\)/g;
795→    let match;
796→    while ((match = parenRegex.exec(block[1])) !== null) {
797→      const decoded = match[1]
798→        .replace(/\\n/g, "\n").replace(/\\r/g, "\r").replace(/\\t/g, "\t")
799→        .replace(/\\\\/g, "\\").replace(/\\\(/g, "(").replace(/\\\)/g, ")");
800→      if (decoded.trim()) textChunks.push(decoded);
801→    }
802→  }
803→  if (textChunks.join(" ").trim().length < 200) {
804→    const streamRegex = /stream\r?\n([\s\S]*?)\r?\nendstream/g;
805→    let sm;
806→    while ((sm = streamRegex.exec(raw)) !== null) {
807→      const readable = sm[1].replace(/[^\x20-\x7E\n\r\t]/g, " ").replace(/\s+/g, " ").trim();
808→      if (readable.length > 50) textChunks.push(readable);
809→    }
810→  }
811→  return textChunks.join(" ").replace(/\s+/g, " ").trim().slice(0, 10000);
812→}
